			pthread_rwlock_rdlock(&client->export_lock);
		if (client->difmap[mapcnt]!=(uint32_t)(-1)) { /* the block is already there */
			DEBUG("Page %llu is at %lu\n", (unsigned long long)mapcnt,
			       (unsigned long)(client->difmap[mapcnt])) ;
