	slash = strrchr(path, '/');
	if (slash != NULL && slash != path) {
		*slash = '\0';
		mkdir_path(path);
		*slash = '/';
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);
	return fd;
}
