static ssize_t treefilesread(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t inblock = TREEPAGESIZE - (a % TREEPAGESIZE);
	ssize_t ret;
	int fd;

	if (len > inblock)
		len = inblock;
	fd = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->tree_lock);
