### treefiles.c

```c
/*
 * Tree files support: store an export in a tree of small block files
 * rather than in a single large file.
 *
 * The exported device is divided into TREEPAGESIZE-sized blocks, each of
 * which is stored in its own file. The block files are spread over a tree
 * of directories with at most TREEDIRSIZE entries per directory; enough
 * nesting levels are used for the tree to be able to hold all blocks of
 * the device. Directory and file names are the base-TREEDIRSIZE digits of
 * the block number, formatted as four hexadecimal digits.
 *
 * This is useful on filesystems that do not handle large files well,
 * e.g. fuse/ftpfs, davfs and other network filesystems.
 */

#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Compute the number of path components (directories plus the block file
 * itself) needed to store all blocks of a device of the given size.
 */
static int tree_depth(off_t size) {
	int depth = 1;
	unsigned long long capacity = TREEDIRSIZE;
	unsigned long long nblocks;

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	if (nblocks < 1)
		nblocks = 1;
	while (capacity < nblocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}

	return depth;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of a treefiles export.
 *
 * @param name root directory of the tree on entry; full path of the
 * block file on return
 * @param lenmax size of the buffer name points at
 * @param size total size of the exported device
 * @param pos offset into the exported device
 * @param ppos [out] offset of pos within the block file
 */
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	int digits[8];
	int i;
	int len;

	for (i = depth - 1; i >= 0; i--) {
		digits[i] = block % TREEDIRSIZE;
		block /= TREEDIRSIZE;
	}

	len = strlen(name);
	while (len > 1 && name[len - 1] == '/') {
		name[--len] = '\0';
	}
	for (i = 0; i < depth; i++) {
		int written = snprintf(name + len, lenmax - len, "/%04X", digits[i]);
		if (written < 0 || written >= lenmax - len)
			return;
		len += written;
	}
	if (ppos)
		*ppos = pos % TREEPAGESIZE;
}
```

