/**
 * Recursively create the directories in the given path, like mkdir -p.
 * Existing directories are left alone; the path is temporarily modified.
 */
void mkdir_path(char *path) {
	char *p;

	for (p = path + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			mkdir(path, 0755);
			*p = '/';
		}
	}
	mkdir(path, 0755);
}
```

