/*
 * Tree files support: store an export in a tree of small block files
 * rather than in a single large file.
 *
 * The exported device is divided into TREEPAGESIZE-sized blocks, each of
 * which lives in a file of its own. The block files are spread over a
 * tree of directories with at most TREEDIRSIZE entries per directory,
 * using as many nesting levels as needed to hold all blocks of the
 * device. Directory and file names are the base-TREEDIRSIZE digits of
 * the block number, formatted as four hexadecimal digits.
 *
 * This is useful to provide a virtual block device on filesystems that
 * do not handle large files well, e.g. fuse/ftpfs, davfs or other
 * network filesystems.
 */

#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Compute the number of path components (directories plus the block
 * file itself) needed to store all blocks of a device of the given
 * size with at most TREEDIRSIZE entries per directory.
 **/
static int tree_depth(off_t size) {
	unsigned long long nblocks;
	unsigned long long capacity = TREEDIRSIZE;
	int depth = 1;

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	if(nblocks < 1)
		nblocks = 1;
	while(capacity < nblocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}

	return depth;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of a treefiles export.
 *
 * @param name root directory of the tree on entry; on return, the full
 * path of the block file
 * @param lenmax size of the buffer name points at
 * @param size total size of the exported device
 * @param pos offset into the exported device
 * @param ppos [out] offset of pos within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	int digits[8];
	int i;
	int len;

	for(i = depth - 1; i >= 0; i--) {
		digits[i] = block % TREEDIRSIZE;
		block /= TREEDIRSIZE;
	}

	len = strlen(name);
	while(len > 1 && name[len - 1] == '/') {
		name[--len] = '\0';
	}
	for(i = 0; i < depth; i++) {
		int written = snprintf(name + len, lenmax - len, "/%04X",
				       digits[i]);
		if(written < 0 || written >= lenmax - len)
			return;
		len += written;
	}
	if(ppos)
		*ppos = pos % TREEPAGESIZE;
}

/**
 * Recursively create the directories in the given path, like mkdir -p.
 * Directories that already exist are left alone.
 *
 * @param path the directory path to create; temporarily modified
 **/
void mkdir_path(char *path) {
	char *p;

	for(p = path + 1; *p; p++) {
		if(*p == '/') {
			*p = '\0';
			mkdir(path, 0755);
			*p = '/';
		}
	}
	mkdir(path, 0755);
}

/**
 * Open the block file holding the data at a given offset of a
 * treefiles export, creating the file (and the directories leading up
 * to it) if asked to.
 *
 * @param name root directory of the tree
 * @param mode open(2) flags for the block file
 * @param size total size of the exported device
 * @param pos offset into the exported device
 * @param mutex protects concurrent creation of directories and files
 * @return a file descriptor for the block file, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char *slash;
	off_t ppos;
	int fd;

	strncpy(path, name, sizeof(path) - 1);
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, &ppos);

	fd = open(path, mode, 0600);
	if(fd >= 0 || errno != ENOENT || !(mode & O_CREAT))
		return fd;

	/*
	 * The block file does not exist yet. Create the directory tree
	 * leading up to it, then the file itself; creations are
	 * serialised so that only one thread does the work.
	 */
	if(pthread_mutex_lock(mutex) != 0)
		return -1;
	slash = strrchr(path, '/');
	if(slash != NULL && slash != path) {
		*slash = '\0';
		mkdir_path(path);
		*slash = '/';
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Remove the block file holding the data at a given offset of a
 * treefiles export, if it exists. Called when a block gets marked as
 * unused; the block will read back as all zeroes afterwards.
 *
 * @param name root directory of the tree
 * @param size total size of the exported device
 * @param pos offset into the exported device
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	off_t ppos;

	strncpy(path, name, sizeof(path) - 1);
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, &ppos);
	unlink(path);
}

