/**
 * Write up to one block to a treefiles export, creating the block file
 * (and the directories leading up to it) if it does not exist yet.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written (len, capped at the
 * block boundary), or -1 in case of an error
 **/
static ssize_t treefiles_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	off_t ppos = a % TREEPAGESIZE;
	size_t inblock = TREEPAGESIZE - ppos;
	ssize_t ret;
	int fd;

	if(len > inblock)
		len = inblock;
	fd = open_treefile(client->exportname, O_RDWR | O_CREAT,
			   client->exportsize, a, &client->tree_lock);
	if(fd < 0)
		return -1;
	ret = pwrite(fd, buf, len, ppos);
	if(ret == (ssize_t)len) {
		if(client->server->flags & F_SYNC) {
			fsync(fd);
		} else if(fua) {
			fdatasync(fd);
		}
	}
	close(fd);

