/**
 * Mark a range of a treefiles export as unused. Block files fully
 * covered by the range are deleted; partially covered blocks are
 * zeroed. The range reads back as all zeroes afterwards.
 *
 * @param a The offset where the range starts
 * @param len The length of the range
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
static int treefiles_discard(off_t a, size_t len, CLIENT *client, int fua) {
	char zeros[TREEPAGESIZE];
	off_t end = a + len;

	memset(zeros, 0, sizeof(zeros));
	while(a < end) {
		off_t blockstart = a - (a % TREEPAGESIZE);
		off_t blockend = blockstart + TREEPAGESIZE;
		size_t wlen;
		ssize_t ret;
		int fd;

		if(blockend > (off_t)client->exportsize)
			blockend = client->exportsize;
		if(a == blockstart && end >= blockend) {
			/* fully covered block: drop the file */
			delete_treefile(client->exportname,
					client->exportsize, blockstart);
			a = blockend;
			continue;
		}
		wlen = (end < blockend ? end : blockend) - a;
		fd = open_treefile(client->exportname, O_RDWR,
				   client->exportsize, a, &client->tree_lock);
		if(fd < 0) {
			if(errno == ENOENT) {
				/* no file: reads already return zeroes */
				a += wlen;
				continue;
			}
			return -1;
		}
		ret = pwrite(fd, zeros, wlen, a % TREEPAGESIZE);
		if(ret == (ssize_t)wlen && fua)
			fdatasync(fd);
		close(fd);
		if(ret != (ssize_t)wlen)
			return -1;
		a += wlen;
	}

	return 0;
}

